CREATE TABLE IF NOT EXISTS "user" (id text PRIMARY KEY,name text NOT NULL,email text NOT NULL UNIQUE,email_verified boolean NOT NULL DEFAULT false,image text,created_at timestamp NOT NULL DEFAULT now(),updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS session (id text PRIMARY KEY,expires_at timestamp NOT NULL,token text NOT NULL UNIQUE,created_at timestamp NOT NULL DEFAULT now(),updated_at timestamp NOT NULL DEFAULT now(),ip_address text,user_agent text,user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS session_user_idx ON session(user_id);
CREATE TABLE IF NOT EXISTS account (id text PRIMARY KEY,account_id text NOT NULL,provider_id text NOT NULL,user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,access_token text,refresh_token text,id_token text,access_token_expires_at timestamp,refresh_token_expires_at timestamp,scope text,password text,created_at timestamp NOT NULL DEFAULT now(),updated_at timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS account_user_idx ON account(user_id);
CREATE TABLE IF NOT EXISTS verification (id text PRIMARY KEY,identifier text NOT NULL,value text NOT NULL,expires_at timestamp NOT NULL,created_at timestamp NOT NULL DEFAULT now(),updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS collections (id text PRIMARY KEY,user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,name text NOT NULL,description text NOT NULL DEFAULT '',created_at timestamp NOT NULL DEFAULT now(),updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS goals (id text PRIMARY KEY,user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,title text NOT NULL,completed boolean NOT NULL DEFAULT false,created_at timestamp NOT NULL DEFAULT now(),updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notes (id text PRIMARY KEY,user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,title text NOT NULL,body text NOT NULL DEFAULT '',resource_type text,resource_id text,created_at timestamp NOT NULL DEFAULT now(),updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS saved_podcasts (id text PRIMARY KEY,user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,url text NOT NULL,title text NOT NULL,kind text NOT NULL,spotify_id text NOT NULL,collection_id text REFERENCES collections(id) ON DELETE SET NULL,created_at timestamp NOT NULL DEFAULT now(),updated_at timestamp NOT NULL DEFAULT now(),UNIQUE(user_id,url));
CREATE TABLE IF NOT EXISTS user_preferences (user_id text PRIMARY KEY REFERENCES "user"(id) ON DELETE CASCADE,interests jsonb NOT NULL DEFAULT '[]',preferences jsonb NOT NULL DEFAULT '{}',updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS learning_paths (id text PRIMARY KEY,slug text NOT NULL UNIQUE,title text NOT NULL,description text NOT NULL,subject text NOT NULL,level text NOT NULL,published boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS path_steps (id text PRIMARY KEY,path_id text NOT NULL REFERENCES learning_paths(id) ON DELETE CASCADE,position integer NOT NULL,title text NOT NULL,description text NOT NULL DEFAULT '',subject_slug text,resource_url text);
CREATE TABLE IF NOT EXISTS learning_progress (id text PRIMARY KEY,user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,path_id text NOT NULL,step_id text NOT NULL,completed boolean NOT NULL DEFAULT false,created_at timestamp NOT NULL DEFAULT now(),updated_at timestamp NOT NULL DEFAULT now(),UNIQUE(user_id,path_id,step_id));
CREATE TABLE IF NOT EXISTS channels (id text PRIMARY KEY,owner_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,slug text NOT NULL UNIQUE,name text NOT NULL,description text NOT NULL DEFAULT '',avatar_url text,approved boolean NOT NULL DEFAULT false,created_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS videos (id text PRIMARY KEY,title text NOT NULL,description text NOT NULL DEFAULT '',creator_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,channel_id text NOT NULL REFERENCES channels(id) ON DELETE CASCADE,subject text NOT NULL,subtopics jsonb NOT NULL DEFAULT '[]',level text NOT NULL DEFAULT 'all',language text NOT NULL DEFAULT 'en',duration_seconds integer,thumbnail_url text,media_asset_ref text,transcript_ref text,published_at timestamp,visibility text NOT NULL DEFAULT 'private',moderation_state text NOT NULL DEFAULT 'pending',processing_status text NOT NULL DEFAULT 'draft',tags jsonb NOT NULL DEFAULT '[]',metrics jsonb NOT NULL DEFAULT '{}',chapters jsonb NOT NULL DEFAULT '[]',resources jsonb NOT NULL DEFAULT '[]',created_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reports (id text PRIMARY KEY,user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,resource_type text NOT NULL,resource_id text NOT NULL,reason text NOT NULL,state text NOT NULL DEFAULT 'pending',created_at timestamp NOT NULL DEFAULT now(),updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS upload_jobs (id text PRIMARY KEY,user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,video_id text REFERENCES videos(id) ON DELETE CASCADE,storage_key text,content_type text,size_bytes integer,state text NOT NULL DEFAULT 'disabled',moderation_result jsonb,created_at timestamp NOT NULL DEFAULT now(),updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS subscriptions (id text PRIMARY KEY,user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,channel_id text NOT NULL REFERENCES channels(id) ON DELETE CASCADE,created_at timestamp NOT NULL DEFAULT now(),updated_at timestamp NOT NULL DEFAULT now(),UNIQUE(user_id,channel_id));
CREATE TABLE IF NOT EXISTS watch_history (id text PRIMARY KEY,user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,video_id text NOT NULL REFERENCES videos(id) ON DELETE CASCADE,position_seconds integer NOT NULL DEFAULT 0,created_at timestamp NOT NULL DEFAULT now(),updated_at timestamp NOT NULL DEFAULT now(),UNIQUE(user_id,video_id));
CREATE TABLE IF NOT EXISTS saved_resources (id text PRIMARY KEY,user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,collection_id text REFERENCES collections(id) ON DELETE SET NULL,resource_type text NOT NULL,resource_id text NOT NULL,created_at timestamp NOT NULL DEFAULT now(),updated_at timestamp NOT NULL DEFAULT now(),UNIQUE(user_id,resource_type,resource_id));
CREATE TABLE IF NOT EXISTS blocked_users (id text PRIMARY KEY,user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,blocked_user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,created_at timestamp NOT NULL DEFAULT now(),updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY,applied_at timestamp NOT NULL DEFAULT now());
INSERT INTO schema_migrations(version) VALUES('0001_foundation') ON CONFLICT DO NOTHING;
